// Single-user relay: host credentials are generated by Render, never committed.
const http = require("node:http"),
  crypto = require("node:crypto");
const { headers, serveStatic } = require("./static.cjs");
const equal = (a, b) => {
  a = Buffer.from(typeof a === "string" ? a : "");
  b = Buffer.from(b);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
};
async function body(req) {
  let data = "";
  for await (const chunk of req) {
    data += chunk;
    if (data.length > 1024 * 1024) throw new Error("Request too large");
  }
  return JSON.parse(data);
}
async function startRelay({
  key = process.env.POFI_RELAY_KEY,
  port = Number(process.env.PORT || 4320),
  host = "0.0.0.0",
  now = Date.now,
} = {}) {
  if (typeof key !== "string" || key.length < 32)
    throw new Error("POFI_RELAY_KEY must contain at least 32 characters.");
  const phoneKey = crypto
    .createHmac("sha256", key)
    .update("pofi-phone-v1")
    .digest("hex");
  let state = null,
    lastSeen = 0,
    instance = null;
  const pending = new Map();
  const online = () => state && now() - lastSeen < 10000;
  const json = (res, code, obj) => {
    if (res.writableEnded || res.destroyed) return;
    res.writeHead(code, { "Content-Type": "application/json" });
    res.end(JSON.stringify(obj));
  };
  const failPending = () => {
    for (const entry of pending.values()) {
      clearTimeout(entry.timeout);
      json(entry.res, 503, { error: "Pofi restarted. Please try again." });
    }
    pending.clear();
  };
  const server = http.createServer(async (req, res) => {
    headers(res);
    const url = new URL(req.url, "http://pofi.local");
    try {
      if (req.method === "GET" && url.pathname === "/healthz")
        return json(res, 200, { ok: true });
      if (url.pathname === "/bridge/sync") {
        if (req.method !== "POST" || !equal(req.headers["x-pofi-host"], key))
          return json(res, 401, { error: "Host authentication failed." });
        const data = await body(req);
        if (
          typeof data.instance !== "string" ||
          !data.state ||
          !["focus", "break"].includes(data.state.mode)
        )
          return json(res, 400, { error: "Invalid host state." });
        if (instance !== data.instance) {
          failPending();
          instance = data.instance;
        }
        state = data.state;
        lastSeen = now();
        for (const result of Array.isArray(data.results) ? data.results : []) {
          const item = pending.get(result.id);
          if (item) {
            clearTimeout(item.timeout);
            pending.delete(result.id);
            json(
              item.res,
              result.error ? 400 : 200,
              result.error ? { error: result.error } : result.state,
            );
          }
        }
        return json(res, 200, {
          phoneKey,
          commands: [...pending].map(([id, item]) => ({
            id,
            action: item.action,
            value: item.value,
          })),
        });
      }
      if (url.pathname.startsWith("/api/")) {
        if (!equal(req.headers["x-pofi-token"], phoneKey))
          return json(res, 401, {
            error: "Scan the internet pairing QR in Pofi.",
          });
        if (!online())
          return json(res, 503, {
            error:
              "Your computer is offline. Open Pofi on Ubuntu to reconnect.",
          });
        if (req.method === "GET" && url.pathname === "/api/state")
          return json(res, 200, state);
        if (req.method === "POST" && url.pathname === "/api/command") {
          if (pending.size >= 20)
            return json(res, 429, {
              error: "Too many pending commands. Please wait.",
            });
          const data = await body(req);
          if (
            ![
              "toggle",
              "reset",
              "skip",
              "early-walk",
              "early-focus",
              "settings",
              "sound",
            ].includes(data.action)
          )
            return json(res, 400, { error: "Unknown action." });
          const id = crypto.randomUUID();
          const timeout = setTimeout(() => {
            pending.delete(id);
            json(res, 504, {
              error:
                "Computer did not respond. Check its connection before retrying.",
            });
          }, 12000);
          pending.set(id, {
            res,
            timeout,
            action: data.action,
            value: data.value,
          });
          res.on("close", () => {
            if (pending.get(id)?.res === res) {
              clearTimeout(timeout);
              pending.delete(id);
            }
          });
          return;
        }
        return json(res, 404, { error: "Not found" });
      }
      serveStatic(req, res, url.pathname);
    } catch {
      return json(res, 400, { error: "Unable to process request." });
    }
  });
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(port, host, resolve);
  });
  return {
    server,
    close: () => {
      failPending();
      return new Promise((resolve) => server.close(resolve));
    },
  };
}
if (require.main === module)
  startRelay()
    .then(() => console.log("Pofi relay is listening."))
    .catch((e) => {
      console.error(e.message);
      process.exitCode = 1;
    });
module.exports = { startRelay };
